// Lista los correos recibidos hoy en la bandeja principal.
// Si el nodo Gmail fallo (sin credencial o error de API),
// devuelve un mensaje claro en vez de romper.
let mails = [];
let gmailOk = false;
try {
  const g = $('Gmail');
  if (g.isExecuted) {
    gmailOk = true;
    mails = g.all().map((item) => item.json);
  }
} catch (e) {
  gmailOk = false;
}

if (!gmailOk) {
  return { text: 'No pude leer Gmail. Revisá que la credencial Google OAuth2 esté cargada en n8n (Settings > Credentials) y que el workflow esté activo.' };
}

if (!mails.length) {
  return { text: 'No recibiste correos hoy.' };
}

const lines = mails.map((m, i) => {
  const from = m.from ? (Array.isArray(m.from) ? m.from.map((f) => f.name || f.email).join(', ') : String(m.from)) : '(sin remitente)';
  const date = m.date ? new Date(m.date) : null;
  const hora = date ? date.toLocaleTimeString('es-AR', { hour: '2-digit', minute: '2-digit', hour12: false }) : '';
  return `${i + 1}. ${hora ? '[' + hora + '] ' : ''}${m.subject || '(sin asunto)'} — de ${from}`;
});

return { text: `Correos de hoy (${mails.length}):\n\n` + lines.join('\n') };
